void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Transforma las coordenadas del píxel a un rango de -1 a 1
    vec2 uv = (2.0 * fragCoord - iResolution.xy) / min(iResolution.y, iResolution.x);

    // Efecto de túnel
    float angle = atan(uv.x, uv.y);
    float radius = length(uv);
    float tunnel = 0.3 / radius + sin(angle * 10.0 - iTime * 2.0) * 0.1;

    // Color basado en la profundidad del túnel
    vec3 color = 0.5 + 0.5 * cos(iTime + vec3(1.0, 2.0, 3.0) + tunnel * 10.0);

    // Salida del color del píxel
    fragColor = vec4(color, 1.0);
}
